43	export function exShowChooser(onPick: (choice: ExChoice) => void, onWatch: (choice: ExChoice) => void = () => {}): void {
44	  const root = el();
45	  if (!root) return;
46	  lockGliderOnTouch(root);
47	  /* Lần trước mất kết nối khi đang xem (explore.exit tải lại trang): đọc cờ một lần rồi xóa, hiện exMpLostChooser */
48	  try {
49	    const lost = sessionStorage.getItem('exMpNotice');   // 'lost' (xem bầu trời dù lượn) | 'lostWalk' (xem người đi dạo: câu nhắc chọn Đi dạo, vì thẻ Dù lượn bị khóa trên điện thoại) | 'lostDrive' (xem xe: nhắc chọn Ô tô) | 'lostBike' (xem xe từ thẻ Xe máy: nhắc chọn Xe máy)
50	    if (lost === 'lost' || lost === 'lostWalk' || lost === 'lostDrive' || lost === 'lostBike') {
51	      sessionStorage.removeItem('exMpNotice');
52	      const n = document.getElementById('exMpLostNote');
53	      if (n) { const k = lost === 'lostWalk' ? 'stLostChooser' : lost === 'lostDrive' ? 'drLostChooser' : lost === 'lostBike' ? 'bkLostChooser' : ''; if (k) { n.dataset.i18n = k; n.textContent = t(k); } n.hidden = false; }
54	    }
55	  } catch { /* bộ nhớ bị chặn */ }
56	  wireLang(root);
57	  /* Ảnh thẻ nạp lười (màn chọn ẩn thì chưa tải; vào thẳng `?explore=…` không tải gì): chưa xong thì trong suốt (.ld) rồi hiện dần; ảnh lỗi thì thẻ còn nền tối + chữ */
58	  root.querySelectorAll<HTMLImageElement>('img.ex-img').forEach((im) => {
59	    if (im.complete && im.naturalWidth) return;
60	    im.classList.add('ld');
61	    im.addEventListener('load', () => im.classList.remove('ld'), { once: true });
62	  });
63	  /* Không dùng { once: true }: từ sảnh bấm Quay lại / Esc thì các thẻ phải chọn lại được. Hộp đã đóng (đã chọn xong) thì bỏ qua */
64	  root.querySelectorAll<HTMLButtonElement>('button[data-pick]').forEach((b) => {
65	    if (b.disabled) return;
66	    b.addEventListener('click', () => {
67	      if (root.hidden) return;
68	      const choice = b.dataset.pick as ExChoice;
69	      /* Đánh dấu thẻ đang chọn (viền vàng, aria-pressed) và đưa ảnh của nó lên đầu sảnh; chỉ là hiển thị, luồng chọn bên dưới giữ nguyên */
70	      root.querySelectorAll<HTMLButtonElement>('button[data-pick]').forEach((o) => { const on = o === b; o.classList.toggle('sel', on); o.setAttribute('aria-pressed', String(on)); });
71	      const im = b.querySelector<HTMLImageElement>('img.ex-img');
72	      root.dataset.mode = choice;
73	      if (im && im.naturalWidth) root.style.setProperty('--ex-hero', `url("${im.currentSrc || im.src}")`); else root.style.removeProperty('--ex-hero');
74	      /* Dù lượn / Đi dạo / Ô tô / Xe máy có máy chủ: sang bước chọn slot + nhập tên (mở kết nối ở đây, không sớm hơn); không có máy chủ: bay / đi / lái một mình ngay như trước.
75	         Ô tô và Xe máy chung 5 chỗ lái (phiên 'drive'); xe máy xin chỗ với veh 1. Thẻ đã chọn đi theo onWatch: người xem chạy module của thẻ đó, nhận lời mời thì lên đúng loại xe */
76	      const kind = choice === 'walk' ? 'walk' : choice === 'car' || choice === 'bike' ? 'drive' : 'fly';
77	      if ((choice === 'glider' || choice === 'walk' || choice === 'car' || choice === 'bike') && exMulti.begin(() => {}, kind, choice === 'bike' ? 1 : 0)) {
78	        const solo = () => { exHideChooser(); onPick(choice); };
79	        exShowLobby(exMulti.session!, { onFly: solo, onWatch: () => { exHideChooser(); onWatch(choice); }, onSolo: solo, onBack: () => b.focus({ preventScroll: true }) });
80	        return;
81	      }
82	      exHideChooser(); onPick(choice);
83	    });
84	  });
85	  const show = () => { root.hidden = false; setUnderInert(root, true); root.querySelector<HTMLButtonElement>('button[data-pick]:not(:disabled)')?.focus({ preventScroll: true }); };
86	  const loading = document.getElementById('loading');
87	  if (!loading || loading.classList.contains('done')) { show(); return; }
88	  const mo = new MutationObserver(() => { if (loading.classList.contains('done')) { mo.disconnect(); show(); } });   // #loading.done được đặt sau khung đầu
89	  mo.observe(loading, { attributes: true, attributeFilter: ['class'] });
90	}
