105	/* Một bước: cổng nhịp quay, sơ tán / chuyển động, hình xe, camera, hiệu ứng đêm */
106	function advance(dt: number, inp: DrInput): void {
107	  if (ctrl) drSetGate(net!, DR_GATE_SWING, ctrl.state !== 'CLOSED');
108	  const s = state!;
109	  if (!drEvacStep(s, net!, dt, ctrl ? drSwingBudget(ctrl) : undefined)) drStep(s, inp, net!, boxes, trNearby(s.x, s.z, CONFIG.drive.ai.radius, boxes), dt);
110	  drCars.place(selfSlot, state!);
111	  drCamPlace(camera, state!, camS, net!, dt);
112	  controls.target.set(state!.x, state!.y, state!.z);   // tâm vùng bóng đổ (main.ts shadowCenter) theo xe
113	  const now = performance.now();
114	  exMulti.update(dt, now, null);     // xe người khác, người bay / đi dạo, nhãn tên; không làm gì khi lái một mình
115	  exMulti.updateDrive(now, state);   // gửi vị trí + vận tốc + góc lái khi đang giữ chỗ (kể cả lúc sơ tán)
116	  drHudUpdate(state!, exDrivers.dots()); drSound.update(state!.v);
117	  exNightStep(dt, false);
118	}
