121	function watchStep(dt: number): void {
122	  if (ctrl) drSetGate(net!, DR_GATE_SWING, ctrl.state !== 'CLOSED');
123	  exMulti.update(dt, performance.now(), null);
124	  const w = exMulti.watchDriver();
125	  if (w) {
126	    drCamPlace(camera, w, camS, net!, dt, !chased); chased = true;
127	    controls.target.set(w.x, w.y, w.z);
128	    _ws.x = w.x; _ws.z = w.z; _ws.yaw = w.yaw; _ws.v = w.v;
129	    drHudUpdate(_ws, exDrivers.dots(w));
130	  }
131	  exNightStep(dt, false);
