245	/* onExit: thoát chung (explore.exit), dùng khi mất kết nối lúc đang xem */
246	export function setupDrive(c: SwingController, onExit: () => void): void {
247	  ctrl = c; exit = onExit;
248	  window.addEventListener('keydown', (e) => {
249	    if (!active() || e.key === 'Escape') return;   // Esc do explore/index.ts xử lý (thoát chung)
250	    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt không điều khiển xe, tránh kẹt phím
251	    if (isField(e.target)) return;                    // gõ trong ô nhập / chọn không điều khiển xe
252	    if (!DR_KEYS.has(e.code)) return;
253	    exMulti.activity();   // phím điều khiển (kể cả tự lặp) tính là còn đó
254	    if (e.code.startsWith('Arrow') || e.code === 'Space') e.preventDefault();   // không cuộn trang, Space không bấm nút đang focus
255	    drKeys.add(e.code);
256	  });
257	  window.addEventListener('keyup', (e) => {
258	    drKeys.delete(e.code);
259	    if (e.code === 'Space' && active() && !isField(e.target)) e.preventDefault();
260	  });
261	  const drop = drBindDrop(window, document, drKeys);
262	  window.addEventListener('focusin', (e) => { if (active() && isField(e.target)) { drop(); touch?.reset(); drSound.horn(false); } });
263	  /* Tab ẩn hoặc mất tiêu điểm: vòng khung có thể dừng nên tắt còi ngay (phím đã nhả ở drBindDrop, cảm ứng tự reset trong touch.ts) */
264	  window.addEventListener('blur', () => drSound.horn(false));
265	  document.addEventListener('visibilitychange', () => { if (document.hidden) drSound.horn(false); });
266	  drSound.bind(document.getElementById('drSoundBtn'), () => cam.mode !== 'bike');   // nút 🔊 / 🔇: cách duy nhất bật tiếng xe khi chưa bật âm thanh chung (nút nhạc ẩn trong chế độ khám phá)
267	  const hud = document.getElementById('drHud');
268	  if (hud) touch = drTouchBind(hud, {
269	    look: (dx, dy) => { if (active()) drCamDrag(camS, dx, dy); },
270	    activity: () => exMulti.activity()
271	  });
272	  /* Kéo chuột trái trên canvas: xoay camera quanh xe (ngón tay vuốt #drLook trong touch.ts) */
273	  let dragId = -1, lx = 0, ly = 0;
274	  canvas.addEventListener('pointerdown', (e) => {
275	    if (!active() || e.pointerType === 'touch' || e.button !== 0) return;
276	    dragId = e.pointerId; lx = e.clientX; ly = e.clientY;
277	    canvas.setPointerCapture(e.pointerId);
278	  });
279	  canvas.addEventListener('pointermove', (e) => {
280	    if (e.pointerId !== dragId) return;
281	    drCamDrag(camS, e.clientX - lx, e.clientY - ly);
282	    lx = e.clientX; ly = e.clientY;
283	  });
284	  const end = (e: PointerEvent) => { if (e.pointerId === dragId) dragId = -1; };
285	  canvas.addEventListener('pointerup', end);
286	  canvas.addEventListener('pointercancel', end);
287	  canvas.addEventListener('lostpointercapture', end);
288	}
